class NaiveBroker {
    private final Map<String, BlockingQueue<String>> topics = new ConcurrentHashMap<>();
    public void createTopic(String name) {
        topics.putIfAbsent(name, new LinkedBlockingQueue<>());
    }
    public void publish(String topic, String msg) throws InterruptedException {
        topics.get(topic).put(msg); // blocks producer if bounded; couples producer to consumer speed
    }
    // FATAL: take() destroys the message. Subscriber B never sees what A consumed.
    // No offset, no replay, no independence. This is a work queue, not Kafka.
    public String consume(String topic) throws InterruptedException {
        return topics.get(topic).take();
    }
}

