import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;

final class Message {
    final long sequence; final String payload;
    Message(long sequence, String payload) { this.sequence = sequence; this.payload = payload; }
}

interface ISubscriber {
    String getId();
    void onMessage(Message m) throws InterruptedException; // may be slow; never called under broker lock
}

class Topic {
    private final String name;
    private final List<Message> log = new ArrayList<>();
    private final ReadWriteLock rw = new ReentrantReadWriteLock();
    private final AtomicLong seq = new AtomicLong(0);
    private final List<TopicSubscriber> workers = new CopyOnWriteArrayList<>();
    Topic(String name) { this.name = name; }
    void addWorker(TopicSubscriber w) { workers.add(w); }
    Message append(String payload) {
        Message m;
        rw.writeLock().lock();
        try { m = new Message(seq.getAndIncrement(), payload); log.add(m); }
        finally { rw.writeLock().unlock(); }
        for (TopicSubscriber w : workers) w.signal(); // signal-only; publish never blocks on consumers
        return m;
    }
    List<Message> readFrom(int offset) {
        rw.readLock().lock();
        try {
            if (offset >= log.size()) return List.of();
            return new ArrayList<>(log.subList(offset, log.size())); // copy so callback runs lock-free
        } finally { rw.readLock().unlock(); }
    }
    int size() { rw.readLock().lock(); try { return log.size(); } finally { rw.readLock().unlock(); } }
}

class TopicSubscriber implements Runnable {
    private final Topic topic; private final ISubscriber sub;
    private final AtomicInteger offset = new AtomicInteger(0);
    private final Object park = new Object();
    private volatile boolean running = true;
    TopicSubscriber(Topic topic, ISubscriber sub) { this.topic = topic; this.sub = sub; }
    void signal() { synchronized (park) { park.notify(); } }
    void reset(int o) { offset.set(Math.max(0, o)); signal(); }
    void stop() { running = false; signal(); }
    public void run() {
        while (running) {
            List<Message> batch = topic.readFrom(offset.get());
            if (batch.isEmpty()) {
                synchronized (park) {
                    try { park.wait(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); return; }
                }
                continue;
            }
            for (Message m : batch) {
                if (!running) return;
                try { sub.onMessage(m); } // outside any topic lock: slow consumer cannot stall log
                catch (Exception e) { break; } // do NOT advance offset: at-least-once retry
                offset.incrementAndGet(); // advance after success only
            }
        }
    }
}

class Broker {
    private final ConcurrentMap<String, Topic> topics = new ConcurrentHashMap<>();
    private final ConcurrentMap<String, TopicSubscriber> subs = new ConcurrentHashMap<>();
    private final ExecutorService pool = Executors.newCachedThreadPool();
    public void createTopic(String name) { topics.putIfAbsent(name, new Topic(name)); }
    public void publish(String topic, String payload) {
        Topic t = topics.get(topic);
        if (t == null) throw new IllegalArgumentException("no topic: " + topic);
        t.append(payload);
    }
    public void subscribe(String topic, ISubscriber s) {
        Topic t = topics.get(topic);
        if (t == null) throw new IllegalArgumentException("no topic: " + topic);
        TopicSubscriber w = new TopicSubscriber(t, s);
        if (subs.putIfAbsent(topic + ":" + s.getId(), w) != null) return;
        t.addWorker(w); pool.execute(w);
    }
    public void resetOffset(String topic, String subId, int o) {
        TopicSubscriber w = subs.get(topic + ":" + subId);
        if (w != null) w.reset(o);
    }
    public void shutdown() { subs.values().forEach(TopicSubscriber::stop); pool.shutdownNow(); }
}

