class Topic:
    def __init__(self):
        self._log, self._lock, self._cond = [], threading.RLock(), threading.Condition()
    def append(self, msg):
        with self._cond:
            self._log.append(msg)
            self._cond.notify_all()  # publishers never wait for consumers
    def read_from(self, off):
        with self._lock:
            return list(self._log[off:])  # copy: process outside lock
class TopicSubscriber(threading.Thread):
    def __init__(self, topic, handler):
        super().__init__(daemon=True)
        self.topic, self.handler, self.offset, self._run = topic, handler, 0, True
    def run(self):
        while self._run:
            batch = self.topic.read_from(self.offset)
            if not batch:
                with self.topic._cond:
                    self.topic._cond.wait(timeout=0.2)
                continue
            for m in batch:
                self.handler(m)  # advance only after success -> at-least-once
                self.offset += 1

// Demonstrates isolation: slow subscriber must not stall fast subscriber or publisher.
class SlowSubscriber implements ISubscriber {
    private final String id;
    SlowSubscriber(String id) { this.id = id; }
    public String getId() { return id; }
    public void onMessage(Message m) throws InterruptedException {
        if (id.equals("slow")) Thread.sleep(200); // simulates slow downstream
        System.out.println(id + " got seq=" + m.sequence + " : " + m.payload);
    }
}
